"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowLeft } from "lucide-react";
import { useState } from "react";
import { createClient } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { useLanguage } from "@/lib/i18n/LanguageContext";

export default function NewLeadPage() {
  const router = useRouter();
  const supabase = createClient();
  const { t } = useLanguage();
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    customer_name: "", phone: "", email: "",
    location: "", source: "offline", notes: "",
  });

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const { data, error } = await supabase.from("leads").insert({
      source: form.source,
      customer_name: form.customer_name || null,
      phone: form.phone || null,
      email: form.email || null,
      location: form.location || null,
      stage: "new",
      quality: "pending",
    }).select("id").single();

    if (data) {
      if (form.notes) {
        await supabase.from("activities").insert({
          lead_id: data.id, type: "note", content: form.notes,
        });
      }
      router.push(`/leads/${data.id}`);
    }
    setSaving(false);
  }

  return (
    <div className="max-w-lg space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()} className="text-gray-400">
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <h1 className="text-2xl font-bold text-white">{t("leads.newLead")}</h1>
      </div>

      <Card className="bg-gray-900 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white text-lg">{t("leads.customerInfo")}</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <Label className="text-gray-300">{t("leads.name")}</Label>
              <Input
                value={form.customer_name}
                onChange={(e) => setForm({ ...form, customer_name: e.target.value })}
                className="bg-gray-950 border-gray-700 text-white mt-1"
                placeholder={t("leads.name")}
              />
            </div>
            <div>
              <Label className="text-gray-300">{t("leads.phone")}</Label>
              <Input
                value={form.phone}
                onChange={(e) => setForm({ ...form, phone: e.target.value })}
                className="bg-gray-950 border-gray-700 text-white mt-1"
                placeholder="+971..."
              />
            </div>
            <div>
              <Label className="text-gray-300">{t("leads.email")}</Label>
              <Input
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                className="bg-gray-950 border-gray-700 text-white mt-1"
                placeholder="email@example.com"
              />
            </div>
            <div>
              <Label className="text-gray-300">{t("leads.location")}</Label>
              <Input
                value={form.location}
                onChange={(e) => setForm({ ...form, location: e.target.value })}
                className="bg-gray-950 border-gray-700 text-white mt-1"
                placeholder="Dubai, Palm Jumeirah..."
              />
            </div>
            <div>
              <Label className="text-gray-300">{t("leads.source")}</Label>
              <select
                value={form.source}
                onChange={(e) => setForm({ ...form, source: e.target.value })}
                className="w-full mt-1 rounded-md bg-gray-950 border border-gray-700 text-white px-3 py-2 text-sm"
              >
                <option value="offline">{t("sourceLabels.offline")}</option>
                <option value="whatsapp">{t("sourceLabels.whatsapp")}</option>
                <option value="meta_ads">{t("sourceLabels.meta_ads")}</option>
                <option value="website">{t("sourceLabels.website")}</option>
                <option value="referral">{t("sourceLabels.referral")}</option>
                <option value="other">{t("sourceLabels.other")}</option>
              </select>
            </div>
            <div>
              <Label className="text-gray-300">{t("leads.notes")}</Label>
              <Textarea
                value={form.notes}
                onChange={(e) => setForm({ ...form, notes: e.target.value })}
                className="bg-gray-950 border-gray-700 text-white mt-1"
                placeholder={t("leads.notes")}
                rows={3}
              />
            </div>
            <Button
              type="submit"
              disabled={saving}
              className="w-full bg-gold-500 hover:bg-gold-600 text-black font-semibold"
            >
              {saving ? t("common.saving") : t("leads.createLead")}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
